"""Generate a standalone, read-only illustrative map. Never claims DB execution."""
from pathlib import Path
import json
steps = [
('C01','Recolha','Medições com fonte e data','10 → 8 → 6 → 7 → 9 h/semana','O C01 existente importa CSV e preserva observações e correções. Estes valores são ilustrações, não resultados lidos de uma base.'),
('C02','Sinais','Deterioração temporal','Candidato, não caso','O c02-v2 existente aplica regras explícitas e guarda o snapshot. Um sinal nunca comprova a causa ou autoriza uma intervenção.'),
('C03','Evidências','Uma promessa histórica verificável','Perfil v1 · referências imutáveis','O c03-v1 existente liga medições, janelas, fonte e perfil histórico. Integridade de evidência não demonstra, por si só, valor realizado.'),
('C04','Objetivo','Reduzir de 10 para 4 horas semanais','Prazo vencido · objetivo não atingido','Política isolada flowreports-demo-v1. Duas médias semanais, cobertura 100%, fonte única. Capacidade do plano, compromisso SaaS e confirmação do cliente são referências distintas, confirmadas por administrador.'),
('C05','Investigação','A integração necessária está desativada','Impedimento documentado','Uma observação integration_status=disabled do C01 sustenta o achado no seu período. Sem prova: aguarda informação. O sistema não afirma que este impedimento é a causa única.'),
('C06','Plano','Restabelecer o fluxo com controlo humano','Intervenção manual · aguarda aprovação','Verificar a configuração, reativar a integração no sistema de origem, confirmar estado e guardar recibo. Se houver erro, revisão humana antes de desativar novamente. Não existe conector externo neste piloto.'),
('C07','Execução','A pessoa autorizada regista o que fez','Aprovação admin · validade 24 horas','Administrador aprova o plano. Operador ou administrador regista a referência da execução humana. O Core valida estado, autorização, versão e idempotência no servidor. O registo não executa nem certifica uma ação externa.'),
('C08','Observação','Dar tempo para medir o resultado','14 dias · duas janelas semanais','O gate persistido começa no registo da execução. O relógio do servidor controla o prazo; não há atalho de tempo no browser. Um pedido prematuro é recusado.'),
('C09','Resultado','Comparar antes e depois','9 → 4 h/semana · cenário ilustrativo','Exige novo pacote C03, duas janelas totalmente posteriores à execução, mesma versão de perfil e mesma fonte. Verifica também uma observação enabled. A melhoria temporal não prova causalidade.'),
('C10','Decisão','Fechar apenas quando há prova suficiente','Resolvido ou continua aberto','Objetivo cumprido nas duas janelas + evidência suficiente + integração verificada permitem encerramento. Se as horas permanecerem em 9, o caso continua aberto, mesmo com execução técnica declarada.'),
]
html = r'''<!doctype html><html lang="pt"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CENTERWAY · mapa do MVP</title>
<style>
:root{color-scheme:dark;--bg:#17181c;--card:#1e2025;--line:#34363d;--muted:#a3a5af;--amber:#e8bb62;--green:#8dccad}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#ececf0;font:14px/1.6 system-ui,sans-serif}button,a{font:inherit}button{cursor:pointer}a{color:var(--amber)}.shell{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:100vh}aside{padding:30px 22px;border-right:1px solid var(--line)}.brand{font-size:18px;letter-spacing:3px;font-weight:700}.brand b{color:var(--amber)}.sub{font-size:11px;color:var(--muted);letter-spacing:1px}.nav{display:flex;flex-direction:column;gap:6px;margin-top:38px}.nav a{padding:10px;color:var(--muted);text-decoration:none;border-radius:6px}.nav a.active{background:#302b21;color:var(--amber)}main{padding:36px;max-width:1500px;width:100%;margin:auto}h1{font-size:27px;letter-spacing:-.7px;margin:12px 0 4px}h2{font-size:17px;margin:0 0 10px}p{margin:6px 0}.muted{color:var(--muted)}.badge{border:1px solid #74613f;border-radius:20px;color:var(--amber);font-size:11px;padding:4px 10px;display:inline-block}.notice{background:#29251e;border:1px solid #615337;border-radius:8px;padding:16px;margin:22px 0}.notice strong{color:var(--amber)}.steps{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:25px 0}.steps button{padding:13px;text-align:left;background:var(--card);border:1px solid var(--line);border-radius:7px;color:inherit}.steps button.selected{border-color:var(--amber);background:#2b271f}.steps small{color:var(--amber);display:block;letter-spacing:1px}.grid{display:grid;grid-template-columns:300px minmax(0,1fr);gap:20px}.card{border:1px solid var(--line);border-radius:9px;background:var(--card);padding:22px}.tenant{color:var(--green);font-size:12px}.facts{margin-top:18px}.facts div{border-top:1px solid var(--line);padding:11px 0}.facts small{color:var(--muted);display:block}.value{font-size:23px;font-variant-numeric:tabular-nums}.result{margin:20px 0;padding:16px;border-left:3px solid var(--amber);background:#26272c}.foot{font-size:12px;color:var(--muted);margin-top:20px}.controls{display:flex;justify-content:space-between;margin-top:24px}.controls button,.switch button{background:#2d2e35;color:inherit;padding:8px 14px;border:1px solid var(--line);border-radius:5px}.controls button:disabled{opacity:.3;cursor:default}.switch{display:flex;gap:8px;flex-wrap:wrap;margin-top:20px}.switch button[aria-pressed=true]{border-color:var(--amber);color:var(--amber)}.chart{display:flex;align-items:end;gap:10px;height:130px;margin:25px 0 20px}.bar{flex:1;background:#756344;border-radius:4px 4px 0 0;position:relative;min-width:25px;text-align:center}.bar:last-child{background:var(--amber);color:#18191b}.bar span{display:block;margin-top:5px}.caption{font-size:11px;color:var(--muted)}.states{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:20px}.states div{border:1px solid var(--line);padding:12px;border-radius:6px;font-size:12px}.states b{display:block;color:var(--amber)}@media(max-width:950px){.shell{grid-template-columns:1fr}aside{border-bottom:1px solid var(--line);padding:15px 20px}.nav{flex-direction:row;margin:10px 0 0;overflow:auto}.grid{grid-template-columns:1fr}.steps{grid-template-columns:repeat(5,1fr)}main{padding:20px}.states{grid-template-columns:1fr}}@media(max-width:540px){.steps{grid-template-columns:repeat(2,1fr)}}
</style><div class="shell"><aside><div class="brand">CENTER<b>WAY</b></div><div class="sub">ACOMPANHAR RESULTADOS</div><nav class="nav"><a href="#overview" data-view="overview">Visão geral</a><a href="#objective" data-view="objective">Objetivo e evidências</a><a class="active" href="#case" data-view="case">Caso e percurso</a><a href="#results" data-view="results">Resultados</a></nav><p class="foot">Mapa sintético<br>Sem sessão ou backend<br>Somente leitura</p></aside><main>
<div class="tenant">FlowReports / Loja Aurora · referência fictícia</div><h1>Do objetivo ao resultado</h1><p class="muted">O Core coordena o percurso. Cada etapa preserva o que sabemos e o que falta demonstrar.</p>
<div class="notice"><strong>Visualização de referência · dados ilustrativos, sem operações.</strong><p>Este ficheiro funciona sem instalação. Não consulta uma base e não é prova de um percurso executado. A aplicação integrada usa autenticação e RPCs PostgreSQL em <code>/app/casos</code>, após instalar a migração numa base descartável.</p></div>
<div class="steps" id="steps"></div><div class="grid"><section class="card"><span class="badge">CASO SINTÉTICO · AURORA</span><h2 style="margin-top:18px">Automatizar relatórios</h2><p class="muted">Objetivo confirmado pelo cliente, compromisso e capacidade documentados separadamente.</p><div class="facts"><div><small>Situação inicial</small><span class="value">10 h<span class="caption"> / semana</span></span></div><div><small>Meta específica do cenário</small><span class="value">≤4 h<span class="caption"> / semana</span></span></div><div><small>Condição investigada</small>Integração de origem ativa</div><div><small>Tipo de intervenção</small>Execução humana autorizada</div><div><small>Política da demonstração</small><code>flowreports-demo-v1</code></div></div></section>
<section class="card"><span class="badge" id="code"></span><h2 id="title" style="font-size:23px;margin-top:14px"></h2><p id="subtitle" class="muted"></p><div class="result" id="status"></div><p id="description"></p><div id="outcomes" hidden><div class="chart" id="chart"></div><div class="caption">Medições ilustrativas: percurso inicial e duas semanas posteriores.</div><div class="switch"><button id="resolved" aria-pressed="true">Ver cenário: meta atingida</button><button id="open" aria-pressed="false">Ver cenário: caso aberto</button></div><p id="decision" style="margin-top:14px"></p></div><div class="controls"><button id="prev">← Etapa anterior</button><button id="next">Próxima etapa →</button></div></section></div>
<div class="states"><div><b>Guardas do Core</b>Tenant, perfil histórico, estado, versão e operação idempotente.</div><div><b>Autorização</b>Administrador aprova; operador regista a execução; leitor consulta.</div><div><b>Critério de encerramento</b>Janela válida + medições suficientes + meta + estado da integração.</div></div><p class="foot">Implementação operacional: C01–C03 preservados; C04–C10 e Core adicionados no repositório. Sem conector externo, execução autónoma, score global, reabertura ou scheduler. A validação completa de segurança e ponta a ponta continua necessária antes de um piloto real.</p></main></div><script>
const steps=__STEPS__;let selected=3;let resolved=true;
const $=id=>document.getElementById(id);
function render(){const s=steps[selected];$('code').textContent=s[0]+' · '+s[1];$('title').textContent=s[2];$('status').textContent=s[3];$('description').textContent=s[4];$('subtitle').textContent='Core / '+s[0]+' / política específica da demonstração';$('steps').innerHTML='';steps.forEach((v,i)=>{const b=document.createElement('button');b.className=i===selected?'selected':'';b.setAttribute('aria-pressed',String(i===selected));const small=document.createElement('small');small.textContent=v[0];b.append(small,document.createTextNode(v[1]));b.onclick=()=>{selected=i;render()};$('steps').append(b)});$('prev').disabled=selected===0;$('next').disabled=selected===9;$('outcomes').hidden=selected<8;renderOutcome()}
function renderOutcome(){const values=[10,8,6,7,9,...(resolved?[4,4]:[9,9])];$('chart').innerHTML='';values.forEach(v=>{const b=document.createElement('div');b.className='bar';b.style.height=(v*11)+'px';const span=document.createElement('span');span.textContent=v+'h';b.append(span);$('chart').append(b)});$('resolved').setAttribute('aria-pressed',String(resolved));$('open').setAttribute('aria-pressed',String(!resolved));$('decision').textContent=resolved?'Exemplo de decisão: ENCERRADO RESOLVIDO — duas semanas <=4h, evidências suficientes e integração verificada.':'Exemplo de decisão: CONTINUA ABERTO — a integração foi reativada, mas o objetivo continua não atingido. Execução não é valor.'}
$('prev').onclick=()=>{selected--;render()};$('next').onclick=()=>{selected++;render()};$('resolved').onclick=()=>{resolved=true;renderOutcome()};$('open').onclick=()=>{resolved=false;renderOutcome()};document.querySelectorAll('[data-view]').forEach(a=>a.onclick=()=>{document.querySelectorAll('[data-view]').forEach(n=>n.classList.remove('active'));a.classList.add('active');const v=a.dataset.view;selected=v==='overview'?0:v==='objective'?3:v==='results'?8:4;render()});render();
</script></html>'''
root=Path(__file__).resolve().parents[2]
(root/'public/mvp-preview.html').write_text(html.replace('__STEPS__',json.dumps(steps,ensure_ascii=False)))
print('Generated public/mvp-preview.html (read-only illustrative map).')
